write.scripts/main.gd:
extends Node

var _ctx
var _score := {"left": 0, "right": 0}
var _rally := 0

func _pack_setup(ctx) -> void:
	_ctx = ctx

func _pack_start() -> void:
	_rally = 0

func _pack_tick(frame: int) -> void:
	_rally = frame

func _pack_state() -> Dictionary:
	return {"score": _score, "rally": _rally}

write.tests/bot_rally.gd:
extends Node

var _ctx
var _frames := 0

func _bot_setup(ctx) -> void:
	_ctx = ctx

func _bot_tick(frame: int) -> void:
	_frames = frame

func _bot_done() -> bool:
	return _frames >= 300

func _bot_result() -> Dictionary:
	return {"ok": true, "summary": "kept the ball in play for 300 frames"}

write.scripts/paddle_ai.gd:
extends RefCounted

func decide(ball_y: float, paddle_y: float, tuning: Dictionary) -> float:
	var err: float = tuning.get("error_m", 0.3)
	if absf(ball_y - paddle_y) < err:
		return 0.0
	return FAKE_SCRIPT_ERROR(ball_y - paddle_y)

extends RefCounted

func decide(ball_y: float, paddle_y: float, tuning: Dictionary) -> float:
	var err: float = tuning.get("error_m", 0.3)
	if absf(ball_y - paddle_y) < err:
		return 0.0
	return signf(ball_y - paddle_y)
